// Demo Mode: three SYNTHETIC scenarios. No AI, no network, never saved to history.
// Triage uses the same deterministic rules as the real flow. Report text is written by us, not generated by a model.
import { buildSummary } from "./symptoms.js";
const BASE = { eye: "right", onset: "months", pain: "none", redness: "no", blur: "none", light: "no", flashes: "no", suddenLoss: "no", injury: "no", history: ["none"], diabetes: "none", text: "" };
export const DEMOS = {
  a: { answers: { ...BASE, history: ["dry_eye"], text: "Mild dryness after long screen days." }, quality: "no_image" },
  b: { answers: { ...BASE, eye: "left", onset: "today", pain: "severe", redness: "yes", blur: "marked", light: "yes", flashes: "yes", suddenLoss: "yes", text: "" }, quality: "no_image" },
  c: { answers: { ...BASE, onset: "days", redness: "yes", text: "" }, quality: "poor" },
};
const BLUR_SVG = "data:image/svg+xml;utf8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><filter id="b"><feGaussianBlur stdDeviation="9"/></filter></defs><rect width="160" height="120" fill="#10151c"/><g filter="url(#b)"><ellipse cx="80" cy="60" rx="55" ry="26" fill="#3a4654"/><circle cx="80" cy="60" r="18" fill="#222a35"/></g><text x="80" y="112" font-size="9" fill="#9fb3c8" text-anchor="middle" font-family="sans-serif">SYNTHETIC</text></svg>');
export function demoContext(id, t, triage) {
  const d = DEMOS[id]; if (!d) return null;
  const tr = triage(d.answers, d.answers.text);
  const key = "demo_" + id;
  const report = {
    image_quality: { overall: d.quality, issues: id === "c" ? [t("demo_c_issue1"), t("demo_c_issue2")] : [] },
    observations: {}, symptom_summary: t(key + "_sum"), limitations: [t("demo_lim1"), t(key + "_lim")], next_steps: [t(key + "_n1"), t(key + "_n2")],
    ai_urgency: null, urgency: tr.level, uncertainty: t("demo_unc"), missing: [],
    reassurance_blocked: id !== "a",
  };
  return { at: new Date().toISOString(), summary: buildSummary(d.answers), report, triage: tr, source: "demo", model: "", thumbs: id === "c" ? { right: BLUR_SVG } : {}, demo: id };
}
